def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "neg": 3, "^": 4}

    def reduce_top():
        op = operators.pop()

        if op == "neg":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            result = a + b
        elif op == "-":
            result = a - b
        elif op == "*":
            result = a * b
        elif op == "^":
            if b < 0:
                raise ArithmeticError
            result = pow(a, b)
        else:
            if b == 0:
                raise ArithmeticError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == "/" else a - b * quotient

        values.append(result)

    i = 0
    n = len(expr)
    expect_operand = True

    try:
        while i < n:
            c = expr[i]

            if c == " ":
                i += 1
                continue

            if "0" <= c <= "9":
                number = 0
                while i < n and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expect_operand = False
                continue

            if c == "(":
                operators.append(c)
                expect_operand = True
            elif c == ")":
                while operators[-1] != "(":
                    reduce_top()
                operators.pop()
                expect_operand = False
            elif c == "-" and expect_operand:
                operators.append("neg")
            else:
                while operators and operators[-1] != "(":
                    top_precedence = precedence[operators[-1]]
                    current_precedence = precedence[c]
                    if top_precedence < current_precedence:
                        break
                    if top_precedence == current_precedence and c == "^":
                        break
                    reduce_top()
                operators.append(c)
                expect_operand = True

            i += 1

        while operators:
            reduce_top()

        return values[0]
    except ArithmeticError:
        return "error"
